public class NQueensCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object count(int n) {
        try {
            return NQueensCounter.countSolutions(n);
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    static String first(int n) {
        try {
            return java.util.Arrays.toString(NQueensCounter.firstSolution(n));
        } catch (RuntimeException e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("countSolutions(1)", 1, count(1));
        check("countSolutions(2)", 0, count(2));
        check("countSolutions(3)", 0, count(3));
        check("countSolutions(4)", 2, count(4));
        check("countSolutions(5)", 10, count(5));
        check("countSolutions(6)", 4, count(6));
        check("countSolutions(8)", 92, count(8));
        check("countSolutions(0)", 0, count(0));
        check("countSolutions(-3)", 0, count(-3));

        check("firstSolution(1)", "[0]", first(1));
        check("firstSolution(3) has none", "[]", first(3));
        check("firstSolution(4)", "[1, 3, 0, 2]", first(4));
        check("firstSolution(6)", "[1, 3, 5, 0, 2, 4]", first(6));
        check("firstSolution(8)", "[0, 4, 7, 5, 2, 6, 1, 3]", first(8));
        check("firstSolution(0)", "[]", first(0));

        int[] eight = NQueensCounter.firstSolution(8);
        boolean legal = eight != null && eight.length == 8;
        if (legal) {
            for (int a = 0; a < 8 && legal; a++) {
                for (int b = a + 1; b < 8 && legal; b++) {
                    if (eight[a] == eight[b] || Math.abs(a - b) == Math.abs(eight[a] - eight[b])) {
                        legal = false;
                    }
                }
            }
        }
        check("firstSolution(8) really is a legal board", true, legal);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

