public class NQueensCounter {

    public static int countSolutions(int n) {
        if (n < 1) {
            return 0;
        }
        return count(new int[n], 0, n);
    }

    private static int count(int[] columns, int row, int n) {
        if (row == n) {
            return 1;
        }
        int total = 0;
        for (int col = 0; col < n; col++) {
            if (safe(columns, row, col)) {
                columns[row] = col;
                total += count(columns, row + 1, n);
            }
        }
        return total;
    }

    public static int[] firstSolution(int n) {
        if (n < 1) {
            return new int[0];
        }
        int[] columns = new int[n];
        return search(columns, 0, n) ? columns : new int[0];
    }

    private static boolean search(int[] columns, int row, int n) {
        if (row == n) {
            return true;
        }
        for (int col = 0; col < n; col++) {
            if (safe(columns, row, col)) {
                columns[row] = col;
                if (search(columns, row + 1, n)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean safe(int[] columns, int row, int col) {
        for (int earlier = 0; earlier < row; earlier++) {
            int taken = columns[earlier];
            if (taken == col || Math.abs(row - earlier) == Math.abs(col - taken)) {
                return false;
            }
        }
        return true;
    }
}
